const rnd = (a, b) => a + Math.random() * (b - a);
const clamp = (v, a = 0, b = 1) => Math.min(b, Math.max(a, v));
const D = Math.PI / 180;

/* ---------- team photos (empty = placeholder stays) ---------- */
$$('.tm-ph').forEach(f => {
  const src = CONFIG.photos[f.dataset.photo];
  if (!src) return;
  const img = new Image();
  img.alt = f.dataset.name; img.loading = 'lazy'; img.decoding = 'async';
  img.onload = () => f.classList.add('has');
  img.onerror = () => img.remove();
  img.src = src; f.prepend(img);
});

/* ---------- apply config ---------- */
$$('[data-url]').forEach(a => {
  const u = CONFIG.urls[a.dataset.url];
  if (u) { a.href = u; a.target = '_blank'; a.rel = 'noopener'; } else a.remove();
});
if (!$('#ctaRow [data-url]').length) { const ctaFallback = $('#ctaFallback'); if (ctaFallback) ctaFallback.hidden = false; }
$$('[data-social]').forEach(li => {
  const u = CONFIG.social[li.dataset.social];
  if (u) { const a = $('a', li); a.href = u; if (/^https?:/i.test(u)) { a.target = '_blank'; a.rel = 'noopener'; } } else li.remove();
});
const socials = Object.values(CONFIG.social).filter(Boolean);
const communityCol = $('#communityCol');
if (communityCol && !$('li', communityCol).length) communityCol.remove();
const partner = $('[data-partner]');
if (partner) { if (CONFIG.partnerEmail) $('a', partner).href = 'mailto:' + CONFIG.partnerEmail; else partner.remove(); }
$('#yr').textContent = new Date().getFullYear();

/* ---------- nav: highlight the section in view ---------- */
(() => {
  const map = new Map($$('.links a').map(a => [a.getAttribute('href').slice(1), a]));
  map.set('partners', map.get('alliances'));
  const io = new IntersectionObserver(es => es.forEach(e => {
    if (!e.isIntersecting) return;
    map.forEach(a => a.classList.remove('on')); map.get(e.target.id).classList.add('on');
  }), {rootMargin: '-45% 0px -50% 0px'});
  map.forEach((a, id) => { const sec = document.getElementById(id); if (sec) io.observe(sec); });
})();

/* ---------- header dock ---------- */
(() => {
  const dock = $('#dock'), btn = $('#dockBtn');
  const set = on => { dock.classList.toggle('open', on); btn.setAttribute('aria-expanded', on); btn.setAttribute('aria-label', on ? 'Close links' : 'Open links'); };
  btn.addEventListener('click', e => { e.stopPropagation(); set(!dock.classList.contains('open')); });
  document.addEventListener('click', e => { if (!dock.contains(e.target)) set(false); });
  addEventListener('keydown', e => { if (e.key === 'Escape' && dock.classList.contains('open')) { set(false); btn.focus(); } });
  const alt = {x: 'x', discord: 'discord', whitepaper: 'docs'};
  $$('.dock-item').forEach(a => {
    const k = a.dataset.link, v = (CONFIG.menu[k] || (alt[k] && CONFIG.social[alt[k]]) || '').trim();
    if (v) {
      a.href = k === 'email' && !/^mailto:/i.test(v) ? 'mailto:' + v : v;
      if (k !== 'email' && k !== 'whitepaper') { a.target = '_blank'; a.rel = 'noopener'; }
      a.dataset.ready = 1;
    } else a.setAttribute('aria-disabled', 'true');
    a.addEventListener('click', e => { if (!a.dataset.ready) e.preventDefault(); set(false); });
  });
})();

