      cam.y = 3.2 + Math.sin(t * .31) * .3 - my * .7;
      yH = H * (.47 + my * .035);

      towers = towers.filter(w => w.z0 + w.D > cam.z - .5);
      fill();
      if (!CALM && t >= nextBoom) {
        const c = towers.filter(w => w.z0 > cam.z + 9 && w.z0 < cam.z + 24);
        if (c.length) explode(c[(Math.random() * c.length) | 0], t);
        nextBoom = t + rnd(5.5, 7.5);
      }
      pulse = Math.max(0, pulse - dt * .55); shake = Math.max(0, shake - dt * 1.3);

      ctx.save();
