      ctx.translate(W / 2 + (Math.random() - .5) * shake * H * .008, H / 2 + (Math.random() - .5) * shake * H * .008);
      ctx.rotate(Math.sin(t * .17) * .012 + mx * .006);
      ctx.translate(-W / 2, -H / 2);

      /* sky and ground */
      let g = ctx.createLinearGradient(0, 0, 0, yH);
