/* ================= TEXT SPLITTING ================= */
function seed(s) {
  s.style.setProperty('--x', rnd(-170, 170).toFixed(0) + 'px');
  s.style.setProperty('--y', rnd(-130, 130).toFixed(0) + 'px');
  s.style.setProperty('--r', rnd(-100, 100).toFixed(0) + 'deg');
  s.style.setProperty('--s', rnd(.3, 1.5).toFixed(2));
  s.style.setProperty('--d', rnd(0, .7).toFixed(2) + 's');
  s.style.setProperty('--t', rnd(.7, 1.7).toFixed(2) + 's');
}
function split(el) {
  const fx = el.dataset.fx;
  if (fx === 'cipher') return;
  el.setAttribute('aria-label', el.textContent.replace(/\s+/g, ' ').trim());
  let wi = 0, si = 0, ci = 0;
  const walk = node => {
    [...node.childNodes].forEach(n => {
      if (n.nodeType === 3) {
        const frag = document.createDocumentFragment();
        n.textContent.split(/(\s+)/).forEach(tok => {
          if (!tok) return;
          if (/^\s+$/.test(tok)) { frag.appendChild(document.createTextNode(' ')); return; }
          const w = document.createElement('span'); w.className = 'w'; w.setAttribute('aria-hidden', 'true');
          w.style.setProperty('--wi', wi); w.style.setProperty('--si', si);
          w.style.setProperty('--sd', si % 2 ? 1 : -1); w.style.setProperty('--wd', wi % 2 ? 1 : -1);
          [...tok].forEach(ch => { const s = document.createElement('span'); s.className = 'ch'; s.textContent = ch; s.style.setProperty('--ci', ci++); if (!fx) seed(s); w.appendChild(s); });
          frag.appendChild(w);
          wi++; if (/[.!?]$/.test(tok)) si++;
        });
        n.replaceWith(frag);
      } else if (n.nodeType === 1) walk(n);
    });
  };
  walk(el);
  el.style.setProperty('--cc', ci);
}
$$('.scatter').forEach(split);
$$('.rv').forEach(el => { el.dataset.k = Math.floor(Math.random() * 5); el.style.setProperty('--d', rnd(0, .3).toFixed(2) + 's'); });

/* ================= REVEAL ================= */
function scramble(el, final, dur = 1500) {
  if (CALM) return;
  const pool = '0123456789ABCDEF#$%&*', lock = [...final].map((_, i) => (i / final.length) * .65 + Math.random() * .35), t0 = performance.now();
  (function f(now) {
    const p = clamp((now - t0) / dur); let out = '';
    [...final].forEach((ch, i) => { out += (p >= lock[i] || /[\s,\-.]/.test(ch)) ? ch : pool[(Math.random() * pool.length) | 0]; });
    el.textContent = out;
    if (p < 1) requestAnimationFrame(f);
  })(t0);
}
function startObservers() {
  const io = new IntersectionObserver(es => es.forEach(e => {
    if (!e.isIntersecting) return;
    e.target.classList.add('in'); io.unobserve(e.target);
    $$('[data-scr]', e.target).forEach(b => scramble(b, b.dataset.scr));
    if (e.target.dataset.fx === 'cipher') scramble(e.target, e.target.textContent, 1300);
  }), {threshold: .18, rootMargin: '0px 0px -6% 0px'});
  $$('.scatter,.rv').forEach(el => io.observe(el));
}
const intro = $('#intro');
if (CALM) {
  $('.scatter,.rv').forEach(e => e.classList.add('in'));
} else if (intro) {
  setTimeout(() => {
    intro.classList.add('leave');
    startObservers();
    setTimeout(() => { if (intro.isConnected) intro.remove(); }, 1000);
  }, 2100);
} else {
  // The current JSX page has no intro overlay; don't skip hero/reveal observers.
  startObservers();
}

/* ================= KINETIC HERO TYPE ================= */
const kinChars = $$('.kin .ch').map(el => ({el, x: 0, y: 0, r: 0}));
function kinetic(mx, my) {
  const reads = kinChars.map(k => { const b = k.el.getBoundingClientRect(); return [b.left + b.width / 2 - k.x, b.top + b.height / 2 - k.y]; });
  kinChars.forEach((k, i) => {
    const dx = reads[i][0] - mx, dy = reads[i][1] - my, d = Math.hypot(dx, dy) || 1, R = 170;
    let tx = 0, ty = 0, tr = 0;
    if (d < R) { const f = Math.pow(1 - d / R, 2) * 70; tx = dx / d * f; ty = dy / d * f; tr = (dx > 0 ? 1 : -1) * f * .5; }
    k.x += (tx - k.x) * .16; k.y += (ty - k.y) * .16; k.r += (tr - k.r) * .16;
    k.el.style.translate = `${k.x.toFixed(1)}px ${k.y.toFixed(1)}px`; k.el.style.rotate = k.r.toFixed(1) + 'deg';
  });
}

