  el._ds = {rot: rnd(0, 360), w: rnd(.18, .75) * (Math.random() < .5 ? -1 : 1), ph: rnd(0, 6.28), f: rnd(.0012, .0036), vis: false, boost: 0, burst: 0};
  DS.push(el); dsIO.observe(el);
