      k.f += (k.t - k.f) * .06;
      k.x += k.dir * k.f * (k.speed + Math.abs(scrollVel) * .55 * (Math.sin(t * .001 + k.speed) > -.2 ? 1 : -.4));
      if (k.x <= -k.w) k.x += k.w;
